<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {NCard,NButton,NInput,NAlert,NTag} from 'naive-ui'
import {api,uncertainMessage} from '../../api'
import {asyncPanel} from '../../asyncPanel'
import {useGmPreferences} from '../../stores/gm/preferences'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
const AppearanceWorkspace=asyncPanel(()=>import('../../components/AppearanceWorkspace.vue'))
const route=useRoute(),router=useRouter(),gm=useGmWorkspace(),character=ref(''),detail=ref<any>(null),loading=ref(false),error=ref(''),initialRecipe=ref<any>(undefined),draftRecipe=ref<any>(null),name=ref(''),notice=ref(''),coverage=ref<any>(null),coverageError=ref('')
const pvf=computed(()=>detail.value?.appearance?.pvf_sha256||detail.value?.pvf_sha256||gm.catalogMeta?.pvf_sha256)
const prefs=useGmPreferences('appearance',()=>pvf.value)
const {items:presets,loading:presetsLoading,saving,error:preferenceError,conflict}=prefs
let generation=0
watch(()=>route.query.charac_no,async value=>{character.value=typeof value==='string'?value:'';detail.value=null;initialRecipe.value=undefined;draftRecipe.value=null;error.value='';if(!character.value)return;const id=Number(character.value);if(!Number.isSafeInteger(id)||id<1){error.value='请输入有效角色编号。';return}const current=++generation;loading.value=true;try{const result=await api('/characters/'+id);if(current!==generation)return;detail.value=result;await prefs.load()}catch(e){if(current===generation)error.value=uncertainMessage(e)}finally{if(current===generation)loading.value=false}},{immediate:true})
function openCharacter(){void router.replace({query:{...route.query,charac_no:character.value.trim()||undefined}})}
async function save(recipe:any){draftRecipe.value=recipe;notice.value='已读取当前试衣方案，请填写方案名称并保存。'}
async function persist(){if(!name.value.trim()||!draftRecipe.value)return;if(await prefs.save(name.value.trim(),draftRecipe.value))notice.value='外观方案已保存，仅用于界面试衣；没有修改游戏装备。'}
async function readCoverage(){coverageError.value='';try{coverage.value=await api('/assets/coverage?state=all&page=1')}catch(e){coverageError.value=uncertainMessage(e)}}
onUnmounted(()=>generation++)
</script>
<template><div class="gm-workspace appearance-page"><NCard title="外观与素材" :bordered="false"><p class="muted">查看存档中的实际外观，或应用保存方案试衣。素材不足时会明确显示缺失原因。</p><form class="appearance-target" @submit.prevent="openCharacter"><NInput v-model:value="character" aria-label="外观角色编号" placeholder="角色编号"/><NButton attr-type="submit" type="primary" :loading="loading">读取角色外观</NButton><NButton secondary @click="router.push('/players')">从玩家中心选择</NButton></form><NAlert v-if="error" type="error" :show-icon="false">{{error}}</NAlert><NAlert v-else-if="!detail&&!loading" type="info" :show-icon="false">先选择一个角色，才能核对实际外观与对应 PVF 方案。</NAlert></NCard>
 <AppearanceWorkspace v-if="detail" :detail="detail" :initial-recipe="initialRecipe" @save="save"/>
 <NCard v-if="detail" title="我的外观方案" :bordered="false"><template #header-extra><NButton text :loading="presetsLoading" @click="prefs.load">刷新方案</NButton></template><NAlert v-if="preferenceError" type="warning">{{preferenceError}}</NAlert><div v-if="draftRecipe" class="appearance-target"><NInput v-model:value="name" maxlength="48" aria-label="外观方案名称" placeholder="为当前试衣命名"/><NButton type="primary" :loading="saving" :disabled="!name.trim()||conflict" @click="persist">{{presets.some(row=>row.name===name.trim())?'更新同名方案':'保存试衣方案'}}</NButton></div><p v-if="notice" role="status" class="field-hint">{{notice}}</p><div v-if="presets.length" class="appearance-presets"><article v-for="row in presets" :key="row.name"><div><strong>{{row.name}}</strong><NTag size="small">v{{row.version}}</NTag><small>{{row.payload?.slots?.length||0}} 个部位 · {{row.payload?.animation||'idle'}}</small></div><div class="button-row"><NButton size="small" @click="initialRecipe={...row.payload};name=row.name">应用试衣</NButton><NButton size="small" :disabled="saving||conflict" @click="prefs.remove(row)">删除方案</NButton></div></article></div><p v-else class="muted">还没有保存的方案。在试衣区选择“保存方案”后命名。</p><p class="field-hint">方案按 PVF 独立保存。应用方案只预览，不改变角色存档或发放权限。</p></NCard>
 <NCard title="素材覆盖与缺失说明" :bordered="false"><p>图标、官方职业插画、默认职业动画与实际角色外观分别核验。默认形象和试衣方案会明确标注来源。</p><div class="button-row"><NButton secondary @click="readCoverage">读取物品图标覆盖</NButton><NButton v-if="detail" secondary @click="router.push('/characters/'+detail.character.charac_no+'?section=appearance')">打开角色外观详情</NButton></div><NAlert v-if="coverageError" type="warning">{{coverageError}}</NAlert><details v-if="coverage"><summary>物品图标覆盖结果</summary><pre>{{JSON.stringify(coverage,null,2)}}</pre></details><details v-if="detail?.appearance?.coverage"><summary>当前角色外观部件覆盖</summary><pre>{{JSON.stringify(detail.appearance.coverage,null,2)}}</pre></details></NCard>
</div></template>
<style scoped>.appearance-page{display:grid;gap:20px}.appearance-target{display:flex;gap:12px;margin:16px 0;flex-wrap:wrap}.appearance-target>.n-input{flex:1;min-width:180px}.appearance-presets{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:12px;margin:16px 0}.appearance-presets article{border:1px solid var(--border-color);border-radius:12px;padding:14px;display:grid;gap:12px}.appearance-presets article>div:first-child{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.appearance-presets small{width:100%;color:var(--text-secondary)}@media(max-width:600px){.appearance-target>.n-button{flex:1}.appearance-target>.n-input{flex-basis:100%}}</style>
